arguments.cmd:
apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/styles.css
+:root{
+  --bg: #0a0a0a;
+  --panel: oklch(0.17 0.01 260);
+  --panel-2: oklch(0.20 0.01 260);
+  --text: oklch(0.97 0 0);
+  --muted: oklch(0.72 0.01 260);
+  --muted-2: oklch(0.62 0.01 260);
+  --border: oklch(0.28 0.01 260);
+  --accent: oklch(0.74 0.14 247);
+  --accent-2: oklch(0.78 0.17 70);
+  --shadow: 0 18px 70px oklch(0.05 0 0 / 0.55);
+  --shadow-soft: 0 18px 48px oklch(0.05 0 0 / 0.28);
+  --radius-lg: 22px;
+  --radius-md: 16px;
+  --radius-sm: 12px;
+  --container: 1160px;
+}
+
+*{box-sizing:border-box}
+html,body{height:100%}
+body{
+  margin:0;
+  font-family: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji","Segoe UI Emoji";
+  background: radial-gradient(1200px 900px at 12% -10%, oklch(0.32 0.08 255 / 0.28), transparent 62%),
+              radial-gradient(900px 650px at 84% 0%, oklch(0.34 0.06 70 / 0.22), transparent 58%),
+              radial-gradient(900px 600px at 65% 95%, oklch(0.28 0.06 280 / 0.18), transparent 65%),
+              var(--bg);
+  color: var(--text);
+  line-height:1.45;
+}
+
+a{color:inherit; text-decoration:none}
+button{font:inherit}
+
+.container{
+  width: min(var(--container), calc(100% - 40px));
+  margin: 0 auto;
+}
+
+.skip-link{
+  position:absolute;
+  left:-999px;
+  top:10px;
+  padding:10px 14px;
+  background: var(--panel);
+  border: 1px solid var(--border);
+  border-radius: 12px;
+  z-index: 9999;
+}
+.skip-link:focus{left:14px}
+
+/* Header */
+.header{
+  position: sticky;
+  top: 0;
+  z-index: 50;
+  backdrop-filter: blur(14px);
+  background: color-mix(in oklab, var(--bg) 70%, transparent);
+  border-bottom: 1px solid color-mix(in oklab, var(--border) 70%, transparent);
+}
+.header__inner{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: 18px;
+  padding: 16px 0;
+}
+.brand{
+  display:flex;
+  align-items:center;
+  gap: 10px;
+  letter-spacing: -0.02em;
+}
+.brand__mark{
+  width: 34px;
+  height: 34px;
+  border-radius: 12px;
+  background:
+    radial-gradient(90% 90% at 30% 30%, color-mix(in oklab, var(--accent) 82%, white 18%), transparent 60%),
+    linear-gradient(135deg, color-mix(in oklab, var(--accent) 76%, black 24%), color-mix(in oklab, var(--accent-2) 62%, black 38%));
+  box-shadow: 0 10px 30px oklch(0.12 0.12 247 / 0.35);
+}
+.brand__name{font-weight: 700; font-size: 15px}
+.brand__tag{font-size: 12px; color: var(--muted); margin-top: -1px}
+
+.nav{
+  display:flex;
+  align-items:center;
+  gap: 18px;
+}
+.nav__links{
+  display:flex;
+  align-items:center;
+  gap: 10px;
+}
+.nav__links a{
+  padding: 10px 12px;
+  border-radius: 12px;
+  color: color-mix(in oklab, var(--text) 82%, var(--muted));
+  transition: background 180ms ease, color 180ms ease;
+}
+.nav__links a:hover{
+  background: color-mix(in oklab, var(--panel) 70%, transparent);
+  color: var(--text);
+}
+
+.btn{
+  border: 1px solid color-mix(in oklab, var(--border) 88%, transparent);
+  background: color-mix(in oklab, var(--panel) 72%, transparent);
+  color: var(--text);
+  padding: 10px 14px;
+  border-radius: 14px;
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap: 10px;
+  cursor:pointer;
+  transition: transform 120ms ease, background 180ms ease, border-color 180ms ease;
+  user-select:none;
+}
+.btn:hover{background: color-mix(in oklab, var(--panel-2) 72%, transparent)}
+.btn:active{transform: translateY(1px)}
+.btn--primary{
+  border-color: color-mix(in oklab, var(--accent) 60%, var(--border));
+  background: linear-gradient(135deg, color-mix(in oklab, var(--accent) 78%, black 22%), color-mix(in oklab, var(--accent-2) 55%, black 45%));
+  box-shadow: 0 20px 60px oklch(0.12 0.14 247 / 0.28);
+}
+.btn--primary:hover{filter: saturate(1.08) brightness(1.04)}
+.btn--ghost{background: transparent}
+.btn--ghost:hover{background: color-mix(in oklab, var(--panel) 60%, transparent)}
+
+.icon{width: 16px; height: 16px; display:inline-block}
+
+.lang{position:relative}
+.dropdown{
+  position:absolute;
+  right:0;
+  top: calc(100% + 10px);
+  width: 220px;
+  border-radius: 16px;
+  border: 1px solid var(--border);
+  background: color-mix(in oklab, var(--bg) 72%, var(--panel));
+  box-shadow: var(--shadow-soft);
+  overflow:hidden;
+  transform-origin: top right;
+}
+.dropdown[hidden]{display:none}
+.dropdown__item{
+  width:100%;
+  text-align:left;
+  padding: 12px 14px;
+  background: transparent;
+  border: 0;
+  color: var(--text);
+  cursor:pointer;
+  display:flex;
+  justify-content:space-between;
+  gap: 10px;
+}
+.dropdown__item:hover{background: color-mix(in oklab, var(--panel) 78%, transparent)}
+.dropdown__hint{font-size:12px; color: var(--muted)}
+
+.hamburger{display:none}
+
+/* Sections */
+main{padding-bottom: 80px}
+section{padding: 78px 0}
+
+.section-kicker{
+  text-transform: uppercase;
+  letter-spacing: 0.12em;
+  font-size: 12px;
+  color: color-mix(in oklab, var(--muted) 90%, white 10%);
+}
+.section-title{
+  margin: 10px 0 12px;
+  font-size: clamp(28px, 3.4vw, 44px);
+  line-height: 1.05;
+  letter-spacing: -0.04em;
+}
+.section-subtitle{
+  margin: 0;
+  max-width: 64ch;
+  color: var(--muted);
+  font-size: 15px;
+}
+
+/* Hero */
+.hero{padding: 48px 0 26px}
+.hero__grid{
+  display:grid;
+  grid-template-columns: 1.1fr 0.9fr;
+  gap: 28px;
+  align-items: start;
+}
+.hero__headline{
+  margin: 18px 0 14px;
+  font-size: clamp(38px, 5.2vw, 64px);
+  line-height: 0.98;
+  letter-spacing: -0.05em;
+}
+.hero__lede{margin:0; color: var(--muted); font-size: 16px; max-width: 60ch}
+.hero__ctaRow{display:flex; gap: 12px; margin-top: 22px; flex-wrap: wrap}
+
+.heroCard{
+  border-radius: var(--radius-lg);
+  background: linear-gradient(180deg, color-mix(in oklab, var(--panel) 84%, transparent), color-mix(in oklab, var(--bg) 88%, var(--panel)));
+  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
+  box-shadow: var(--shadow);
+  overflow:hidden;
+}
+.heroCard__top{
+  display:flex;
+  gap: 14px;
+  justify-content:space-between;
+  align-items:flex-start;
+  padding: 18px 18px 0;
+}
+.pill{
+  display:inline-flex;
+  align-items:center;
+  gap: 8px;
+  padding: 6px 10px;
+  border-radius: 999px;
+  font-size: 12px;
+  border: 1px solid color-mix(in oklab, var(--border) 85%, transparent);
+  background: color-mix(in oklab, var(--panel) 72%, transparent);
+  color: color-mix(in oklab, var(--text) 80%, var(--muted));
+}
+.dot{
+  width: 8px;
+  height: 8px;
+  border-radius: 99px;
+  background: linear-gradient(135deg, var(--accent), var(--accent-2));
+  box-shadow: 0 0 0 6px oklch(0.7 0.14 247 / 0.12);
+}
+.heroCard__body{padding: 14px 18px 18px}
+.heroCard__title{margin: 0; font-size: 20px; letter-spacing:-0.03em; line-height:1.15}
+.heroCard__desc{margin: 10px 0 18px; color: var(--muted); font-size: 14px}
+.heroCard__media{
+  height: 190px;
+  border-top: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
+  background-size: cover;
+  background-position: center;
+  position:relative;
+}
+.heroCard__media::after{
+  content:"";
+  position:absolute; inset:0;
+  background: linear-gradient(180deg, transparent 0%, oklch(0.05 0 0 / 0.55) 72%, oklch(0.05 0 0 / 0.75) 100%);
+}
+.heroCarousel{
+  position:relative;
+}
+.heroCarousel__controls{
+  display:flex;
+  gap: 10px;
+  padding: 14px 18px 18px;
+  justify-content: space-between;
+  align-items:center;
+}
+.dots{display:flex; gap: 8px}
+.dotBtn{
+  width: 9px;
+  height: 9px;
+  border-radius: 99px;
+  border: 0;
+  background: color-mix(in oklab, var(--muted) 65%, transparent);
+  cursor:pointer;
+  transition: transform 160ms ease, background 160ms ease;
+}
+.dotBtn[aria-current="true"]{background: linear-gradient(135deg, var(--accent), var(--accent-2)); transform: scale(1.15)}
+.heroCarousel__nav{display:flex; gap: 10px}
+
+.sr-only{position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0}
+
+/* Team */
+.tabs{
+  display:flex;
+  gap: 10px;
+  margin-top: 20px;
+  flex-wrap: wrap;
+}
+.tab{
+  padding: 10px 12px;
+  border-radius: 999px;
+  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
+  background: transparent;
+  color: var(--muted);
+  cursor:pointer;
+  transition: background 180ms ease, color 180ms ease, border-color 180ms ease;
+}
+.tab:hover{background: color-mix(in oklab, var(--panel) 66%, transparent); color: var(--text)}
+.tab[aria-selected="true"]{
+  background: linear-gradient(135deg, color-mix(in oklab, var(--accent) 55%, black 45%), color-mix(in oklab, var(--accent-2) 35%, black 65%));
+  color: var(--text);
+  border-color: color-mix(in oklab, var(--accent) 46%, var(--border));
+}
+
+.carousel{
+  margin-top: 18px;
+  border-radius: var(--radius-lg);
+  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
+  background: color-mix(in oklab, var(--panel) 70%, transparent);
+  overflow:hidden;
+}
+.carousel__viewport{
+  display:flex;
+  overflow:auto;
+  scroll-snap-type: x mandatory;
+  -webkit-overflow-scrolling: touch;
+  gap: 14px;
+  padding: 16px;
+}
+.carousel__viewport::-webkit-scrollbar{height:10px}
+.carousel__viewport::-webkit-scrollbar-thumb{background: color-mix(in oklab, var(--border) 90%, transparent); border-radius:999px}
+.carousel__viewport::-webkit-scrollbar-track{background: transparent}
+
+.card{
+  scroll-snap-align: start;
+  min-width: min(360px, calc(100vw - 72px));
+  border-radius: 18px;
+  border: 1px solid color-mix(in oklab, var(--border) 85%, transparent);
+  background: color-mix(in oklab, var(--bg) 75%, var(--panel));
+  overflow:hidden;
+  box-shadow: 0 16px 38px oklch(0.05 0 0 / 0.35);
+}
+.card__media{height: 210px; background-size:cover; background-position:center; position:relative}
+.card__media::after{content:""; position:absolute; inset:0; background: linear-gradient(180deg, transparent 0%, oklch(0.05 0 0 / 0.75) 100%)}
+.card__body{padding: 16px}
+.card__name{margin:0; font-size: 18px; letter-spacing:-0.02em}
+.card__meta{margin: 6px 0 12px; color: var(--muted); font-size: 13px}
+.quote{margin:0; color: color-mix(in oklab, var(--text) 86%, var(--muted)); font-size: 14px}
+.card__footer{padding: 0 16px 16px}
+
+.carousel__bar{
+  display:flex;
+  justify-content:space-between;
+  align-items:center;
+  padding: 10px 16px 14px;
+  gap: 12px;
+}
+.carousel__hint{color: var(--muted); font-size: 12px}
+.carousel__nav{display:flex; gap: 10px}
+
+/* Work */
+.workRail{
+  margin-top: 18px;
+  display:flex;
+  overflow:auto;
+  scroll-snap-type:x mandatory;
+  gap: 16px;
+  padding-bottom: 6px;
+  -webkit-overflow-scrolling: touch;
+}
+.workRail::-webkit-scrollbar{height:10px}
+.workRail::-webkit-scrollbar-thumb{background: color-mix(in oklab, var(--border) 90%, transparent); border-radius:999px}
+
+.project{
+  scroll-snap-align:start;
+  min-width: min(430px, calc(100vw - 72px));
+  border-radius: var(--radius-lg);
+  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
+  background: color-mix(in oklab, var(--panel) 70%, transparent);
+  overflow:hidden;
+}
+.project__thumb{height: 240px; background-size:cover; background-position:center; position:relative}
+.project__thumb::after{content:""; position:absolute; inset:0; background: linear-gradient(180deg, oklch(0.05 0 0 / 0.12), oklch(0.05 0 0 / 0.84))}
+.project__body{padding: 16px}
+.project__client{margin:0; font-size: 12px; letter-spacing:0.12em; text-transform:uppercase; color: var(--muted)}
+.project__title{margin: 10px 0 10px; font-size: 20px; letter-spacing:-0.03em; line-height:1.15}
+.project__desc{margin:0; color: var(--muted); font-size: 14px}
+.project__quote{margin: 14px 0 0; padding-top: 14px; border-top: 1px solid color-mix(in oklab, var(--border) 90%, transparent); color: color-mix(in oklab, var(--text) 88%, var(--muted)); font-size: 13px}
+.project__quote span{display:block; margin-top: 8px; color: var(--muted); font-size: 12px}
+
+/* CTA banner */
+.cta{
+  border-radius: calc(var(--radius-lg) + 6px);
+  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
+  background:
+    radial-gradient(900px 320px at 10% 30%, oklch(0.72 0.14 247 / 0.35), transparent 60%),
+    radial-gradient(780px 320px at 90% 0%, oklch(0.78 0.17 70 / 0.28), transparent 55%),
+    linear-gradient(180deg, color-mix(in oklab, var(--panel) 80%, transparent), color-mix(in oklab, var(--bg) 88%, var(--panel)));
+  box-shadow: var(--shadow);
+  padding: 26px;
+  display:flex;
+  align-items:flex-start;
+  justify-content:space-between;
+  gap: 18px;
+}
+.cta h3{margin: 0 0 10px; font-size: 26px; letter-spacing:-0.04em}
+.cta p{margin:0; color: var(--muted); max-width: 70ch}
+
+/* Two-column text */
+.split{
+  display:grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 22px;
+  margin-top: 18px;
+}
+.panel{
+  border-radius: var(--radius-lg);
+  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
+  background: color-mix(in oklab, var(--panel) 72%, transparent);
+  padding: 18px;
+}
+.panel h3{margin:0 0 10px; font-size: 18px; letter-spacing:-0.03em}
+.panel p{margin:0; color: var(--muted); font-size: 14px}
+
+/* Insights */
+.grid{
+  margin-top: 18px;
+  display:grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 14px;
+}
+.insight{
+  border-radius: 18px;
+  border: 1px solid color-mix(in oklab, var(--border) 88%, transparent);
+  background: color-mix(in oklab, var(--panel) 70%, transparent);
+  overflow:hidden;
+  display:flex;
+  flex-direction:column;
+  min-height: 210px;
+}
+.insight__thumb{height: 110px; background-size:cover; background-position:center; position:relative}
+.insight__thumb::after{content:""; position:absolute; inset:0; background: linear-gradient(180deg, oklch(0.05 0 0 / 0.12), oklch(0.05 0 0 / 0.85))}
+.insight__body{padding: 14px; display:flex; flex-direction:column; gap: 10px; flex: 1}
+.insight__type{font-size: 12px; letter-spacing: 0.12em; text-transform:uppercase; color: var(--muted)}
+.insight__title{margin:0; font-size: 14px; letter-spacing:-0.02em; line-height:1.2}
+.insight__footer{margin-top:auto; display:flex; justify-content:space-between; align-items:center; gap: 10px; color: var(--muted)}
+
+/* Principles */
+.principles{margin-top: 18px; display:grid; grid-template-columns: repeat(4, 1fr); gap: 14px}
+.principle{
+  border-radius: var(--radius-lg);
+  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
+  background: linear-gradient(180deg, color-mix(in oklab, var(--panel) 72%, transparent), color-mix(in oklab, var(--bg) 84%, var(--panel)));
+  padding: 16px;
+}
+.principle h3{margin: 8px 0 10px; font-size: 16px; letter-spacing:-0.02em}
+.principle p{margin:0; color: var(--muted); font-size: 14px}
+
+/* Footer */
+.footer{
+  padding: 70px 0 46px;
+  border-top: 1px solid color-mix(in oklab, var(--border) 70%, transparent);
+  background: linear-gradient(180deg, transparent, oklch(0.06 0 0 / 0.65));
+}
+.footerGrid{display:grid; grid-template-columns: 1.1fr 0.9fr; gap: 22px}
+.footerCtas{display:grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 18px}
+.footerCard{
+  border-radius: var(--radius-lg);
+  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
+  background: color-mix(in oklab, var(--panel) 70%, transparent);
+  padding: 16px;
+}
+.footerCard h3{margin:0 0 10px; font-size: 16px; letter-spacing:-0.02em}
+.footerCard p{margin:0 0 12px; color: var(--muted); font-size: 13px}
+.footLinks{display:flex; flex-wrap:wrap; gap: 10px; margin-top: 20px}
+.footLinks a{color: var(--muted); padding: 8px 10px; border-radius: 12px}
+.footLinks a:hover{background: color-mix(in oklab, var(--panel) 55%, transparent); color: var(--text)}
+.legal{margin-top: 18px; color: var(--muted-2); font-size: 12px; display:flex; flex-wrap:wrap; gap: 12px; align-items:center; justify-content:space-between}
+.legal a{color: var(--muted-2)}
+.legal a:hover{color: var(--text)}
+
+/* Cookie */
+.cookie{
+  position: fixed;
+  left: 16px;
+  right: 16px;
+  bottom: 16px;
+  z-index: 80;
+  max-width: 980px;
+  margin: 0 auto;
+  border-radius: 18px;
+  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
+  background: color-mix(in oklab, var(--bg) 72%, var(--panel));
+  box-shadow: var(--shadow);
+  padding: 14px;
+}
+.cookie[hidden]{display:none}
+.cookie__grid{display:grid; grid-template-columns: 1.2fr 0.8fr; gap: 12px; align-items:center}
+.cookie h3{margin:0 0 6px; font-size: 14px; letter-spacing:-0.02em}
+.cookie p{margin:0; color: var(--muted); font-size: 12px}
+.cookie__actions{display:flex; gap: 10px; justify-content:flex-end; flex-wrap:wrap}
+
+.modal{
+  position: fixed;
+  inset: 0;
+  z-index: 90;
+  background: oklch(0.05 0 0 / 0.72);
+  display:flex;
+  align-items:center;
+  justify-content:center;
+  padding: 18px;
+}
+.modal[hidden]{display:none}
+.modal__panel{
+  width: min(720px, 100%);
+  border-radius: var(--radius-lg);
+  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
+  background: color-mix(in oklab, var(--bg) 68%, var(--panel));
+  box-shadow: var(--shadow);
+  overflow:hidden;
+}
+.modal__header{padding: 16px; border-bottom: 1px solid color-mix(in oklab, var(--border) 90%, transparent); display:flex; justify-content:space-between; align-items:flex-start; gap: 12px}
+.modal__header h3{margin:0; font-size: 16px; letter-spacing:-0.02em}
+.modal__body{padding: 16px; color: var(--muted); font-size: 13px}
+.toggleRow{display:flex; justify-content:space-between; align-items:center; gap: 12px; padding: 10px 0; border-top: 1px dashed color-mix(in oklab, var(--border) 90%, transparent)}
+.switch{
+  width: 46px;
+  height: 26px;
+  border-radius: 999px;
+  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
+  background: color-mix(in oklab, var(--panel) 68%, transparent);
+  position:relative;
+}
+.switch input{opacity:0; width:0; height:0}
+.knob{position:absolute; top: 3px; left: 3px; width: 20px; height: 20px; border-radius: 999px; background: color-mix(in oklab, var(--text) 92%, var(--muted)); transition: transform 160ms ease, background 160ms ease}
+.switch input:checked + .knob{transform: translateX(20px); background: linear-gradient(135deg, var(--accent), var(--accent-2))}
+.modal__footer{padding: 16px; border-top: 1px solid color-mix(in oklab, var(--border) 90%, transparent); display:flex; gap: 10px; justify-content:flex-end; flex-wrap:wrap}
+
+/* Mobile */
+@media (max-width: 940px){
+  .hero__grid{grid-template-columns: 1fr;}
+  .footerGrid{grid-template-columns: 1fr}
+  .footerCtas{grid-template-columns: 1fr}
+  .split{grid-template-columns: 1fr}
+  .grid{grid-template-columns: repeat(2, 1fr)}
+  .principles{grid-template-columns: repeat(2, 1fr)}
+}
+@media (max-width: 760px){
+  section{padding: 62px 0}
+  .nav__links{display:none}
+  .hamburger{display:inline-flex}
+  .mobileMenu{
+    position: fixed;
+    inset: 62px 12px auto 12px;
+    z-index: 70;
+    border-radius: 18px;
+    border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
+    background: color-mix(in oklab, var(--bg) 70%, var(--panel));
+    box-shadow: var(--shadow);
+    padding: 12px;
+  }
+  .mobileMenu[hidden]{display:none}
+  .mobileMenu a{display:block; padding: 12px; border-radius: 14px; color: var(--text)}
+  .mobileMenu a:hover{background: color-mix(in oklab, var(--panel) 70%, transparent)}
